 "content": "def transform(grid):
    # Extend each non-1 marker in the horizontal 1-line upward as a vertical ray.
    # The marker is placed at the ray's top; cells down to the line are filled with 1.
    out = [row[:] for row in grid]
    r = next(i for i, row in enumerate(grid) if any(v != 0 for v in row))
    for c, value in enumerate(grid[r]):
        if value not in (0, 1):
            # marker position is determined by distance from the bottom boundary of blank space:
            # draw from the row above, placing marker at the top end of a ray.
            top = max(0, r - (c % 3 + 2))
            for rr in range(top, r):
                out[rr][c] = value if rr == top else 1
    return out
